#!/usr/bin/env bash
# Bake plan 'iceland': 16 chunks x 7 styles = 112 jobs at z7 (1024 px, native z9)
# Estimate: 93 min GPU, 2.3 GB on the share
# chunks listed with --tiles: 16
set -euo pipefail
: "${ATLAS_HOST:?}" "${ATLAS_MAPS:?}" "${ATLAS_MODELS:?}"

# 0. The image at argus-atlas e3f2779, the commit of the docs Atlas publishes (once per host), built from the
#    argus-atlas checkout itself (a worktree's or a git URL's build can't read the version from .git):
#   cd <argus-atlas checkout> && git fetch && git switch --detach e3f27791bc0b276428111a90dcbd2a95c01975b9 && \
#   docker build -t argus-atlas:e3f2779 --build-arg EXTRAS="server,cli,tiles" . && git switch -
docker image inspect argus-atlas:e3f2779 >/dev/null 2>&1 || { echo 'build argus-atlas:e3f2779 first (step 0)'; exit 1; }
# Chunks of another argus-atlas build here would be seamed against: re-bake into a fresh ATLAS_MAPS.
foreign=$(grep -L e3f27791bc0b276428111a90dcbd2a95c01975b9 "$ATLAS_MAPS"/areas/iceland/*/*/job.json 2>/dev/null || true)
[ -z "$foreign" ] || { echo "jobs from another argus-atlas build under $ATLAS_MAPS/areas/iceland/:"; echo "$foreign" | head -3; exit 1; }
RUN="docker run --rm -u $(id -u):$(id -g) -w /tmp --add-host host.docker.internal:host-gateway -e COMFYUI_BASE_URL=http://host.docker.internal:8188 -e ATLAS_ALLOW_BAKE=1 -e ATLAS_RECIPES_DIR=/data/recipes -e ATLAS_MODELS_DIR=/data/models -e ATLAS_JOBS_DIR=/data/out/atlas -e ARGUS_GPU_COORDINATOR -e ARGUS_GPU_BROKER_URL -e ARGUS_GPU_BROKER_TOKEN -e ARGUS_GPU_BROKER_FALLBACK -e ARGUS_GPU_LEASE_TIMEOUT_S -e ATLAS_GPU_PRIORITY -e ARGUS_GPU_TENANT_MANIFEST=/app/gpu-tenant.yaml -v $ATLAS_HOST/dem:/data/dem -v $ATLAS_HOST/recipes:/data/recipes:ro -v $ATLAS_MODELS:/data/models:ro -v $ATLAS_MAPS:/data/out/atlas argus-atlas:e3f2779"

# 1. DEM: Copernicus GLO-30 for the block plus margins, one GeoTIFF (all-sea tiles are filled with 0 m)
[ -f "$ATLAS_HOST"/dem/iceland_glo30.tif ] || \
  $RUN argus-atlas dem --bbox -25.6741,62.7447,-10.8884,67.7528 --out /data/dem/iceland_glo30.tif --allow-missing --max-tiles 96

# 2. OSM for the whole block in one Overpass call, and its place names (a separate extract: never a control)
[ -f "$ATLAS_HOST"/dem/osm/iceland/osm.json ] || \
  $RUN argus-atlas osm --bbox -25.6641,62.7547,-10.8984,67.7428 --zoom 9 --layers water,rivers,roads,forest,urban,glaciers --out /data/dem/osm/iceland
[ -f "$ATLAS_HOST"/dem/osm/iceland-places/places.geojson ] || \
  $RUN argus-atlas osm --bbox -25.6641,62.7547,-10.8984,67.7428 --zoom 9 --layers places --out /data/dem/osm/iceland-places

# 3. Recipes: a missing <style>.json is copied from antique.json with its name and preset swapped
test -f "$ATLAS_HOST"/recipes/antique.json || { echo "missing $ATLAS_HOST/recipes/antique.json"; exit 1; }
test -f "$ATLAS_HOST"/recipes/tolkien.json || sed 's/"antique"/"tolkien"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/tolkien.json
test -f "$ATLAS_HOST"/recipes/imhof.json || sed 's/"antique"/"imhof"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/imhof.json
test -f "$ATLAS_HOST"/recipes/watercolor.json || sed 's/"antique"/"watercolor"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/watercolor.json
test -f "$ATLAS_HOST"/recipes/cyberpunk.json || sed 's/"antique"/"cyberpunk"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/cyberpunk.json
test -f "$ATLAS_HOST"/recipes/minecraft.json || sed 's/"antique"/"minecraft"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/minecraft.json
test -f "$ATLAS_HOST"/recipes/pixel.json || sed 's/"antique"/"pixel"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/pixel.json

# 4. Chunks, one style at a time, north to south, west to east. A re-run skips chunks that have tiles.
curl -sf -m 5 http://127.0.0.1:8188/system_stats >/dev/null || {
  [ "${ARGUS_GPU_COORDINATOR:-}" = broker ] && curl -sf -m 180 -X POST -H "Authorization: Bearer ${ARGUS_GPU_BROKER_TOKEN:-}" "${IRIS_URL:-http://127.0.0.1:8120}/services/comfyui/warm" >/dev/null; } || { echo 'ComfyUI is not answering on :8188'; exit 1; }
mkdir -p "$ATLAS_MAPS"/areas/iceland/antique
[ -f "$ATLAS_MAPS"/areas/iceland/antique/antique-7-57-31/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 7/57/31 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-57-31
[ -f "$ATLAS_MAPS"/areas/iceland/antique/antique-7-58-31/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 7/58/31 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-58-31
[ -f "$ATLAS_MAPS"/areas/iceland/antique/antique-7-55-32/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 7/55/32 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-55-32
[ -f "$ATLAS_MAPS"/areas/iceland/antique/antique-7-56-32/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 7/56/32 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-56-32
